diff --git a/src/ui/input.c b/src/ui/input.c
index 85faea0..2a6684b 100644
--- a/src/ui/input.c
+++ b/src/ui/input.c
@@ -82,8 +82,8 @@ static const struct {
     [PAD_R] = {"r", GAMEPAD_BUTTON_RIGHT_TRIGGER_1, KEY_R},
 };

-// A button held when the Shell hides or the runtime restarts is ignored until released, so the Circle
-// that closes the Shell does not reach the Deck App.
+// A button held when the Shell hides is ignored until released, so the Circle that closes the Shell does not reach
+// the Deck App. One held when the runtime starts otherwise presses on its first sample.
 typedef enum { PAD_STATE_UP, PAD_STATE_DOWN, PAD_STATE_IGNORED } PadState;
 static PadState pad_states[PAD_BUTTON_COUNT];
 static bool pad_ignore_held = false;
@@ -295,7 +299,6 @@ void input_clear_focus(void)
     clear_focus();
     for (int i = 0; i < PAD_BUTTON_COUNT; i++)
         pad_states[i] = PAD_STATE_UP;
-    pad_ignore_held = true;
 }

 void input_ignore_held_pad_buttons(void)

diff --git a/src/ui/input.h b/src/ui/input.h
index 3307db1..0b3ddd9 100644
--- a/src/ui/input.h
+++ b/src/ui/input.h
@@ -41,7 +41,8 @@ void input_cancel_text_input(void);
 // The text to draw in Text Input id while it is edited in place (the desktop host), or NULL.
 const char *input_editing_text(const char *id);

-// Forget Focus, held Pad Buttons and any edit. Called when the Deck App runtime starts or stops.
+// Forget Focus, held Pad Buttons and any edit. Called when the Deck App runtime starts or stops. A Pad Button
+// still held presses again on the next sample unless input_ignore_held_pad_buttons asked otherwise.
 void input_clear_focus(void);

 // Ignore Pad Buttons held right now until they are released, e.g. the Circle that hides the Shell.

diff --git a/tests/input_harness.c b/tests/input_harness.c
index fac9259..b8f6ec9 100644
--- a/tests/input_harness.c
+++ b/tests/input_harness.c
@@ -176,8 +177,18 @@ static void test_pad_buttons(void)

     input_clear_focus();
     pad(PAD_CIRCLE, true);
+    pad(PAD_CIRCLE, true);
     pad(PAD_CIRCLE, false);
-    expect_events("", "a runtime restart forgets held Pad Buttons without ending them");
+    expect_events("pad:circle:pressstart pad:circle:pressend",
+                  "a button held through a runtime start presses once, without ending the old press");
+
+    pad(PAD_SQUARE, true);
+    drain();
+    input_ignore_held_pad_buttons();
+    input_clear_focus();
+    pad(PAD_SQUARE, true);
+    pad(PAD_SQUARE, false);
+    expect_events("", "a button held when the Shell hides to restart the runtime stays ignored");

     gamepad((GamepadSample){.confirm = true});
     gamepad((GamepadSample){.up = true, .down = true});
